def find_duplicate_subtrees(root):
    ids, seen, out = {}, Counter(), []

    def key(node):
        if node is None:
            return 0
        triple = (key(node.left), node.val, key(node.right))
        uid = ids.setdefault(triple, len(ids) + 1)
        seen[uid] += 1
        if seen[uid] == 2:
            out.append(node)
        return uid

    key(root)
    return out

def find_duplicate_subtrees(root):
    seen, out = Counter(), []

    def key(node):
        if node is None:
            return "#"
        s = f"({node.val},{key(node.left)},{key(node.right)})"
        seen[s] += 1
        if seen[s] == 2:
            out.append(node)
        return s

    key(root)
    return out
